{
  "passages": [
    {
      "id": "m45",
      "about_topic": true,
      "says": "rule: avoid passing in fog (condition from heading 'Fog › DO'); 'Be patient', 'changing lanes' and 'crossing traffic' are not passing"
    },
    {
      "id": "m48",
      "about_topic": true,
      "says": "rule: avoid passing in a whiteout (condition from heading 'Whiteouts › DO'); 'Be patient', 'changing lanes' and 'crossing traffic' are not passing"
    },
    {
      "id": "m46",
      "about_topic": true,
      "says": "rule: don't speed up to pass a vehicle moving slowly in fog (condition from heading 'Fog › Don't'); 'get away from a vehicle that is following too closely' is about a close follower, not passing"
    },
    {
      "id": "m47",
      "about_topic": true,
      "says": "rule: don't pass other vehicles in fog (condition from heading 'Fog › REMEMBER'); 'Remain calm and patient' and 'speed up suddenly' are not passing"
    },
    {
      "id": "m49",
      "about_topic": true,
      "says": "rule: don't attempt to pass a vehicle moving slowly in a whiteout (condition from heading 'Whiteouts › DON'T'); 'get away from a vehicle that is following too closely' is about a close follower, not passing"
    },
    {
      "id": "m73",
      "about_topic": true,
      "says": "fact: on freeways several snow plows may be staggered across the road, passing a ridge of snow from plow to plow; rule: do not try to pass between them, because there is not enough room to pass safely and the ridge of wet snow can throw the vehicle out of control"
    }
  ],
  "statements": [
    {
      "id": "s1",
      "type": "RULE",
      "force": "ADVISORY",
      "force_from": "text (\"Avoid passing\"); imperative (\"Don't pass\")",
      "text": "a driver SHOULD NOT pass another vehicle WHEN driving in fog",
      "sources": [
        {
          "id": "m45",
          "quote": "Avoid passing, changing lanes and crossing traffic."
        },
        {
          "id": "m47",
          "quote": "Don't pass other vehicles or speed up suddenly."
        }
      ],
      "flags": [],
      "links": [],
      "note": "m45 and m47 state the same advice for fog, so they make one statement. 'Changing lanes', 'crossing traffic', 'speed up suddenly' and the patience reminders are not about passing."
    },
    {
      "id": "s2",
      "type": "RULE",
      "force": "ADVISORY",
      "force_from": "text (\"Avoid passing\")",
      "text": "a driver SHOULD NOT pass another vehicle WHEN driving in a whiteout",
      "sources": [
        {
          "id": "m48",
          "quote": "Avoid passing, changing lanes and crossing traffic."
        }
      ],
      "flags": [],
      "links": [],
