      "force_from": "imperative (\"Don't speed up\")",
      "text": "a driver SHOULD NOT speed up to pass a vehicle moving slowly WHEN driving in fog",
      "sources": [
        {
          "id": "m46",
          "quote": "Don't speed up to pass a vehicle moving slowly or to get away from a vehicle that is following too closely."
        }
      ],
      "flags": [],
