      "note": "The alternative purpose 'to get away from a vehicle that is following too closely' is about a close follower, not overtaking, so it is not extracted."
    },
    {
      "id": "s4",
      "type": "RULE",
      "force": "ADVISORY",
      "force_from": "imperative (\"Don't attempt\")",
      "text": "a driver SHOULD NOT attempt to pass a vehicle moving slowly WHEN driving in a whiteout",
      "sources": [
        {
          "id": "m49",
          "quote": "Don't attempt to pass a vehicle moving slowly or to get away from a vehicle that is following too closely."
        }
      ],
      "flags": [],
      "links": [],
      "note": "The alternative purpose 'to get away from a vehicle that is following too closely' is about a close follower, not overtaking, so it is not extracted."
    },
    {
      "id": "s5",
      "type": "FACT",
      "force": null,
      "force_from": null,
      "text": "FACT on freeways, several snow plows may be staggered across the road, clearing all lanes at the same time by passing a ridge of snow from plow to plow",
      "sources": [
        {
          "id": "m73",
          "quote": "On freeways, several snow plows may be staggered across the road, clearing all lanes at the same time by passing a ridge of snow from plow to plow."
        }
      ],
      "flags": [],
      "links": [],
      "note": "'Passing' here means the plows transfer the ridge of snow to each other, not overtaking; the fact describes the situation the plow rule applies in."
    },
    {
      "id": "s6",
      "type": "RULE",
      "force": "ADVISORY",
      "force_from": "imperative (\"Do not try\")",
      "text": "a driver SHOULD NOT try to pass between the snow plows WHEN the road is a freeway AND several snow plows are staggered across the road BECAUSE it is extremely dangerous: there is not [?enough] room to pass [?safely] AND the ridge of wet snow can throw the vehicle out of control",
      "sources": [
        {
          "id": "m73",
          "quote": "Do not try to pass between them. This is extremely dangerous because there is not enough room to pass safely, and the ridge of wet snow can throw your vehicle out of control."
        }
      ],
      "flags": [
        {
          "code": "J",
          "span": "enough",
          "note": "No measure of how much room is enough."
        },
        {
          "code": "J",
          "span": "safely",
          "note": "No objective standard for passing safely."
        }
      ],
      "links": [
        "s5"
      ],
      "note": "'Them' refers to the snow plows. 'Do not try' is a plain command with a danger warning but no legal wording, so it stays advice."
    }
  ]
